#!/usr/bin/env python3
"""Write deterministic local evidence/index reports from preserved final inputs."""
from pathlib import Path
import json,hashlib
H=Path(__file__).resolve().parent;R=next(p for p in H.parents if (p/'AGENTS.md').exists());sources=set();ledger=[]
for spec in sorted((H/'specs').glob('*.json')):
 for a in json.loads(spec.read_text())['areas']:
  paths=a['contextPaths']+[str(spec.relative_to(R))];sources.update(paths)
  ledger.append({'municipality':a['municipality'],'name':a['name'],'publicEvidenceUrls':a['urls'],'sourceInputPaths':paths,'observedAndInferredEvidence':a['note'],'actualGeometryAnchors':a['anchors'],'sourceObservationMode':'preserved native OSM roads/surfaces and web connector text; no native municipal PDF boundary tracing','estimated':True,'lowConfidence':True,'completeConventionalExtentEstablished':False})
for p in (H/'research').glob('*.json'):sources.add(str(p.relative_to(R)))
sources.update(str(p.relative_to(R)) for p in [H/'task-selection.json',H/'map-registration.json',H/'cached-pomaz-map-registration.json'])
manifest=[]
for rel in sorted(sources):
 p=R/rel;manifest.append({'path':rel,'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
(H/'source-manifest.json').write_text(json.dumps({'sourceFiles':manifest,'osmSnapshot':'2026-11-12T21:23:05Z','osmPbfSha256':'224897876ea131bcf0cb420e789640402d63aabe5e1491785aa4fca813aa641a','sharedContexts':'../contexts/<contextKey>/; all used files are listed and hashed above','networkRequired':False,'additionalPbfScanPerformed':False},ensure_ascii=False,indent=2)+'\n')
(H/'evidence-ledger.json').write_text(json.dumps({'features':ledger,'osmAttribution':'© OpenStreetMap contributors','osmLicense':'ODbL-1.0','osmLicenseUrl':'https://www.openstreetmap.org/copyright','publicPdfCopiesDownloaded':False,'publicEvidenceRetainedAs':'archived web connector text results in research/; URLs retained in per-feature ledger/specifications','mapViewportsAreBoundaries':False},ensure_ascii=False,indent=2)+'\n')
(H/'unresolved.json').write_text(json.dumps({'assignedTargetCount':68,'attemptedTargetCount':68,'collectedTargetCount':68,'unresolved':[],'completeCityCoverageEstablished':False,'nationalCoverageEstablished':False,'remainingUncertainty':'All 68 outputs are rough locality search-area estimates. Historical outer fields, parent/child overlap, planning-vs-everyday names, wooded transitions and estate phases remain uncertain; see per-feature notes. Zero unresolved assigned names does not imply exhaustive locality inventories or exact boundaries.','especiallyUncertainHistoricalFieldExtents':['Foktő / Ökörjárás','Tököl / Petőfitanya','Szalkszentmárton / Cifrahíd-tanya','Kunszentmiklós / Bösztör','Kunszentmiklós / Bösztörpuszta','Diósd / Alsó- és Felsőgazdagdűlő','Nagymaros / Rigóhegy']},ensure_ascii=False,indent=2)+'\n')
(H/'aliases-proposed.json').write_text(json.dumps({'verifiedAliasProposals':[],'identityMergesPerformed':False,'keptDistinct':['Györgyhegy and Györgyliget','Róka-hegy and Rókahegyi lakópark','Margitliget and Szociális Missziótársulat','Farkasverem and Felsőhegy','Felsőtag and Tihanyi lakópark','Bösztör and Bösztörpuszta','Omszk park, Tópart and Omszki lake','Dujmó lakópark and unverified Lakihegyi/Massányi names'],'reason':'Public evidence supports related/overlapping localities but does not establish identity equivalence for a safe alias merge.'},ensure_ascii=False,indent=2)+'\n')
(H/'WORK-STATE.json').write_text(json.dumps({'status':'frozen-complete','date':'2026-11-15','assignment':'task-selection.json','attemptedTargetCount':68,'featureCount':68,'estimatedCount':68,'nativeQuarterPolygonCount':0,'municipalityCount':23,'remainingAssignedNames':0,'unresolvedAssignedNames':0,'activeCollectionTask':False,'writeScope':'data/neighborhoods/expansion-20261115-round4/shard-2/','completeCityCoverageEstablished':False,'nationalCoverageEstablished':False,'validationReport':'validation.json','evidenceLedger':'evidence-ledger.json','sourceManifest':'source-manifest.json','aliases':'aliases-proposed.json','parentHandlesIntegrationAndPublishing':True},ensure_ascii=False,indent=2)+'\n')
print('Finalized evidence for',len(ledger),'features and',len(manifest),'preserved source files')
